import * as rt from '@midnight-ntwrk/compact-runtime';
import { Contract, ledger } from './c/index.js';
let sk = new Uint8Array(32).fill(1), sk2 = new Uint8Array(32).fill(2);
let cur = sk;
const c = new Contract({ secretKey: (ctx) => [ctx.privateState, cur] });
const cpk = rt.sampleContractAddress ? null : null;
let r = c.initialState(rt.createConstructorContext({}, '0'.repeat(64)));
let st = r.currentContractState;
let ctx = rt.createCircuitContext(rt.sampleContractAddress(), '0'.repeat(64), st, {});
const pk = (k)=>c.circuits.publicKey(ctx,k).result;
const A=pk(sk), B=pk(sk2);
const show=(t)=>{const l=ledger(ctx.currentQueryContext.state); console.log(t,'total',l.totalSupply,'A',l.balances.member(A)?l.balances.lookup(A):0,'B',l.balances.member(B)?l.balances.lookup(B):0)};
const call=(n,...a)=>{try{const o=c.impureCircuits[n](ctx,...a);ctx=o.context;return o.result}catch(e){console.log(n,'FAILED:',e.message)}};
cur=sk; call('mint',A,100n); show('mint 100 to A');
call('transfer',B,30n); show('A->B 30');
call('burn',20n); show('A burn 20');
call('transfer',B,999n); call('burn',999n);
cur=sk2; call('mint',B,5n);
console.log('B balanceOf', call('balanceOf',B));
cur=sk; call('transfer',A,10n); show('self transfer');
call('mint',A,18446744073709551615n);
show('after overflow mint');
EOF
