cd $TMPDIR/run && cat > t.mjs <<'EOF'
import * as rt from '@midnight-ntwrk/compact-runtime';
import { Contract, ledger, pureCircuits } from './c/index.js';
const sk = new Uint8Array(32).fill(1), sk2 = new Uint8Array(32).fill(2);
let cur = sk;
const c = new Contract({ secretKey: (ctx) => [ctx.privateState, cur] });
const cpk = '0'.repeat(64);
const r = await c.initialState(rt.createConstructorContext({}, cpk));
let ctx = rt.createCircuitContext({circuitId:'mint', contractAddress: rt.sampleContractAddress(), coinPublicKeyOrZswapState: cpk, contractState: r.currentContractState, privateState: {}});
const A = pureCircuits.publicKey(sk), B = pureCircuits.publicKey(sk2);
const L = () => ledger(ctx.currentQueryContext.state);
const show = (t) => { const l = L(); console.log(t, '| total', l.totalSupply, '| A', l.balances.member(A)?l.balances.lookup(A):0n, '| B', l.balances.member(B)?l.balances.lookup(B):0n, '| entries', l.balances.size()); };
const call = async (n, ...a) => { try { const o = await c.circuits[n](ctx, ...a); ctx = o.context; return o.result } catch (e) { console.log('  ', n, 'FAILED:', e.message) } };
console.log('admin==A', Buffer.from(L().admin).equals(Buffer.from(A)));
show('init');
await call('mint', A, 100n); show('mint 100 to A');
await call('transfer', B, 30n); show('A->B 30');
await call('burn', 20n); show('A burn 20');
await call('transfer', B, 999n); await call('burn', 999n); show('after failed ops');
cur = sk2; await call('mint', B, 5n); show('B tries mint');
console.log('balanceOf B', await call('balanceOf', B), 'unknown', await call('balanceOf', new Uint8Array(32).fill(9)));
cur = sk; await call('transfer', A, 10n); show('self transfer');
await call('mint', A, 18446744073709551615n); show('overflow mint');
EOF
node t.mjs 2>&1 | head -30

